@Test
public void testWbSearchEntities() throws MediaWikiApiErrorException, IOException {
    List<WbSearchEntitiesResult> results = action.wbSearchEntities("abc", "en", null, null, null, null, null);
    assertEquals(7, results.size());
    WbSearchEntitiesResult firstResult = results.get(0);
    assertEquals("Q169889", firstResult.getEntityId());
    assertEquals(firstResult.getConceptUri(), "http://www.wikidata.org/entity/Q169889");
    assertEquals(firstResult.getUrl(), "//www.wikidata.org/wiki/Q169889");
    assertEquals("Q169889", firstResult.getTitle());
    assertEquals(170288, firstResult.getPageId());
    assertEquals("American Broadcasting Company", firstResult.getLabel());
    assertEquals("American broadcast television network", firstResult.getDescription());
    WbSearchEntitiesResult.Match match = new JacksonWbSearchEntitiesResult.JacksonMatch("alias", "en", "ABC");
    assertEquals(match, firstResult.getMatch());
    List<String> aliases = new ArrayList<>();
    aliases.add("ABC");
    assertEquals(aliases, firstResult.getAliases());
}

