public static Parser<?> term(String name) {
    if (name.equals(">>")) {
        return adjacent(">>>").not().next(adjacent(">>"));
    }
    if (name.equals("<<") || name.equals(">>>")) {
        return adjacent(name);
    }
    return TERMS.token(name);
}

