static Parser<Relation> join(Parser<Relation> rel, Parser<Expression> cond) {
    Parser.Reference<Relation> ref = Parser.newReference();
    Parser<Relation> lazy = ref.lazy();
    Parser<Relation> atom = aliasable(ExpressionParser.paren(lazy).or(rel));
    Parser<UnaryOperator<Relation>> crossJoin = TerminalParser.phrase("cross join").next(atom).map(r -> l -> new CrossJoinRelation(l, r));
    Parser<Relation> parser = atom.postfix(Parsers.or(joinOn(INNER_JOIN, lazy, cond), joinOn(LEFT_JOIN, lazy, cond), joinOn(RIGHT_JOIN, lazy, cond), joinOn(FULL_JOIN, lazy, cond), crossJoin));
    ref.set(parser);
    return parser;
}

