public static void quoteIfNeeded(StringBuilder buf, String str, String delim) {
    if (str == null) {
        return;
    }
    int len = str.length();
    if (len == 0) {
        return;
    }
    int ch;
    for (int i = 0; i < len; i++) {
        ch = str.codePointAt(i);
        if (delim.indexOf(ch) >= 0) {
            quote(buf, str);
            return;
        }
    }
    buf.append(str);
}

