public static String unquote(String s) {
    if (!StringUtils.hasText(s)) {
        return s;
    }
    int l = s.length();
    int i = 0;
    for (; i < l; i++) {
        char c = s.charAt(i);
        if (c == '"')
            break;
    }
    if (i == l)
        return s;
    boolean quoted = true;
    boolean sloshed = false;
    StringBuilder buffer = new StringBuilder();
    buffer.append(s, 0, i);
    i++;
    for (; i < l; i++) {
        char c = s.charAt(i);
        if (quoted) {
            if (sloshed) {
                buffer.append(c);
                sloshed = false;
            } else if (c == '"')
                quoted = false;
            else if (c == '\\')
                sloshed = true;
            else
                buffer.append(c);
        } else if (c == '"')
            quoted = true;
        else
            buffer.append(c);
    }
    return buffer.toString();
}

