public static Method findMethod(Class<?> clazz, String name) {
    for (Method me : clazz.getDeclaredMethods()) {
        if (me.getName().equalsIgnoreCase(name)) {
            return me;
        }
    }
    if (clazz.getSuperclass() != null) {
        return findMethod(clazz.getSuperclass(), name);
    }
    return null;
}

