public static Object[] toArray(Object obj, int objType) {
    Object[] values;
    switch(objType) {
        case ZealotConst.OBJTYPE_ARRAY:
            values = (Object[]) obj;
            break;
        case ZealotConst.OBJTYPE_COLLECTION:
            values = ((Collection<?>) obj).toArray();
            break;
        default:
            values = new Object[] { obj };
    }
    return values;
}

