public static <T> CloseableObservableWithReset<T> cache(final Observable<T> source, final long duration, final TimeUnit unit, final Scheduler scheduler) {
    final AtomicReference<CachedObservable<T>> cacheRef = new AtomicReference<CachedObservable<T>>();
    final AtomicReference<Optional<Scheduler.Worker>> workerRef = new AtomicReference<Optional<Scheduler.Worker>>(Optional.<Scheduler.Worker>absent());
    CachedObservable<T> cache = new CachedObservable<T>(source);
    cacheRef.set(cache);
    Runnable closeAction = new Runnable() {

        @Override
        public void run() {
            while (true) {
                Optional<Scheduler.Worker> w = workerRef.get();
                if (w == null) {
                    break;
                } else {
                    if (workerRef.compareAndSet(w, null)) {
                        if (w.isPresent()) {
                            w.get().dispose();
                        }
                        workerRef.set(null);
                        break;
                    }
                }
            }
        }
    };
    Runnable resetAction = new Runnable() {

        @Override
        public void run() {
            startScheduledResetAgain(duration, unit, scheduler, cacheRef, workerRef);
        }
    };
    return new CloseableObservableWithReset<T>(cache, closeAction, resetAction);
}

