    t.setMethod(HttpMethod.GET);
    t.setRequestBody("Hello ${name}! Dear ${name} would you like some ${product}?");
    final InputColumn<?> col1 = new MockInputColumn<>("foo");
    t.setInputAndVariables(new InputColumn[] { col1 }, new String[] { "${name}" });
    t.init();
    assertEquals("Hello world! Dear world would you like some ${product}?", t.applyVariablesToString(t.requestBody, new MockInputRow().put(col1, "world")));
    assertEquals("Hello ! Dear  would you like some ${product}?", t.applyVariablesToString(t.requestBody, new MockInputRow().put(col1, null)));
    final InputColumn<?> col2 = new MockInputColumn<>("bar");
    t.setInputAndVariables(new InputColumn[] { col1, col2 }, new String[] { "${name}", "${product}" });
    assertEquals("Hello customer! Dear customer would you like some tea?", t.applyVariablesToString(t.requestBody, new MockInputRow().put(col1, "customer").put(col2, "tea")));
    t.close();
}

