public void handle(final Event event) {
    final Consumer<Event> handler = handlers.get(event.getType());
    if (handler == null) {
        LOGGER.warn("No specific event handler is registered for {}:{}.", event.getType(), event.getBody());
    } else {
        eventHandlingExecutor.execute(new Runnable() {

            @Override
            public void run() {
                handler.accept(event);
            }
        });
    }
    eventHandlingExecutor.execute(new Runnable() {

        @Override
        public void run() {
            handlers.get("*").accept(event);
        }
    });
}

