    if (channel == null) {
        throw new InvalidArgumentException("setChannel Channel can not be null");
    }
    if (null != this.channel && this.channel != channel) {
        throw new InvalidArgumentException(format("Can not add orderer %s to channel %s because it already belongs to channel %s.", name, channel.getName(), this.channel.getName()));
    }
    logger.debug(format("%s setting channel %s", toString(), channel));
    this.channel = channel;
    this.channelName = channel.getName();
    toString = null;
}

