public String toString() {
    StringBuilder s = new StringBuilder("");
    s.append(type.getSimpleName());
    if (genericTypes.size() >= 1) {
        s.append("<");
        s.append(genericTypes.get(0));
    }
    for (int i = 1; i < genericTypes.size(); i++) {
        s.append(", ");
        s.append(genericTypes.get(i));
    }
    if (genericTypes.size() >= 1) {
        s.append(">");
    }
    return s.toString();
}

