@Override
public void appendValue(DatabaseType databaseType, StringBuilder sb, List<ArgumentHolder> columnArgList) throws SQLException {
    sb.append('(');
    boolean first = true;
    for (Object value : objects) {
        if (value == null) {
            throw new IllegalArgumentException("one of the IN values for '" + columnName + "' is null");
        }
        if (first) {
            first = false;
        } else {
            sb.append(", ");
        }
        super.appendArgOrValue(databaseType, fieldType, sb, columnArgList, value);
        int len = sb.length();
        if (len > 0 && sb.charAt(len - 1) == ' ') {
            sb.setLength(len - 1);
        }
    }
    sb.append(") ");
}

