@Test
public void testCountOf() throws Exception {
    Dao<Foo, Integer> dao = createDao(Foo.class, true);
    assertEquals(0, dao.countOf());
    Foo foo = new Foo();
    assertEquals(1, dao.create(foo));
    assertEquals(1, dao.countOf());
    assertEquals(1, dao.create(foo));
    assertEquals(2, dao.countOf());
}

