public static LinkedBuffer writeRawVarInt32(int value, final WriteSession session, LinkedBuffer lb) {
    final int size = computeRawVarint32Size(value);
    if (lb.offset + size > lb.buffer.length)
        lb = new LinkedBuffer(session.nextBufferSize, lb);
    final byte[] buffer = lb.buffer;
    int offset = lb.offset;
    lb.offset += size;
    session.size += size;
    if (size == 1)
        buffer[offset] = (byte) value;
    else {
        for (int i = 0, last = size - 1; i < last; i++, value >>>= 7) buffer[offset++] = (byte) ((value & 0x7F) | 0x80);
        buffer[offset] = (byte) value;
    }
    return lb;
}

