public static void pushImage(final DockerClient docker, final String imageName, final List<String> imageTags, final Log log, final DockerBuildInformation buildInfo, final int retryPushCount, final int retryPushTimeout, final boolean skipPush) throws MojoExecutionException, DockerException, InterruptedException {
    if (skipPush) {
        log.info("Skipping docker push");
        return;
    }
    int attempt = 0;
    do {
        final AnsiProgressHandler ansiProgressHandler = new AnsiProgressHandler();
        final DigestExtractingProgressHandler handler = new DigestExtractingProgressHandler(ansiProgressHandler);
        try {
            log.info("Pushing " + imageName);
            docker.push(imageName, handler);
            if (imageTags != null) {
                final String imageNameNoTag = getImageNameWithNoTag(imageName);
                for (final String imageTag : imageTags) {
                    final String imageNameAndTag = imageNameNoTag + ":" + imageTag;
                    log.info("Pushing " + imageNameAndTag);
                    docker.push(imageNameAndTag, new AnsiProgressHandler());
                }
            }
        } catch (DockerException e) {
            if (attempt < retryPushCount) {
                log.warn(String.format(PUSH_FAIL_WARN_TEMPLATE, imageName, retryPushTimeout / 1000, attempt + 1, retryPushCount));
                sleep(retryPushTimeout);
                continue;
            } else {
                throw e;
            }
        }
        if (buildInfo != null) {
            final String imageNameWithoutTag = parseImageName(imageName)[0];
            buildInfo.setDigest(imageNameWithoutTag + "@" + handler.digest());
        }
        break;
    } while (attempt++ <= retryPushCount);
}

