@Override
public void trim(String str) {
    if (Strings.isEmpty(str)) {
        return;
    }
    int start = sql.lastIndexOf(str);
    if (start == -1) {
        return;
    }
    int end = sql.length();
    boolean needTrim = true;
    for (int i = start + str.length(); i < end; i++) {
        if (sql.charAt(i) != ' ') {
            needTrim = false;
            break;
        }
    }
    if (needTrim) {
        sql.delete(start, end);
    }
}

