@CanIgnoreReturnValue
public Key register(Watchable watchable, Iterable<? extends WatchEvent.Kind<?>> eventTypes) throws IOException {
    JimfsPath path = checkWatchable(watchable);
    Key key = super.register(path, eventTypes);
    Snapshot snapshot = takeSnapshot(path);
    synchronized (this) {
        snapshots.put(key, snapshot);
        if (pollingFuture == null) {
            startPolling();
        }
    }
    return key;
}

