boolean isCharEscaped(String input, int charAt) {
    if (charAt < 0 || charAt >= input.length()) {
        return false;
    }
    int current = charAt;
    while (current > 0 && input.charAt(current - 1) == '\\') {
        current--;
    }
    return (charAt - current) % 2 != 0;
}

