int[] impliedElements(int anc, int desc) {
    if (desc == SCRIPT_TAG || desc == STYLE_TAG) {
        return ZERO_INTS;
    }
    FreeWrapper wrapper = desc != TEXT_NODE && desc < FREE_WRAPPERS.length ? FREE_WRAPPERS[desc] : null;
    if (wrapper != null) {
        if (anc < wrapper.allowedContainers.length && !wrapper.allowedContainers[anc]) {
            return wrapper.implied;
        }
    }
    if (desc != TEXT_NODE) {
        int[] implied = impliedElements.getElementIndexList(anc, desc);
        if (implied.length != 0) {
            return implied;
        }
    }
    int[] oneImplied = null;
    if (anc == OL_TAG || anc == UL_TAG) {
        oneImplied = LI_TAG_ARR;
    } else if (anc == SELECT_TAG) {
        oneImplied = OPTION_TAG_ARR;
    }
    if (oneImplied != null) {
        if (desc != oneImplied[0]) {
            return LI_TAG_ARR;
        }
    }
    return ZERO_INTS;
}

