                    permissions = arr[2];
                } else {
                    throw new IllegalArgumentException("Invalid device specification: " + deviceStr);
                }
            }
        case 2:
            {
                if (validDeviceMode(arr[1])) {
                    permissions = arr[1];
                } else {
                    dst = arr[1];
                }
            }
        case 1:
            {
                src = arr[0];
                break;
            }
        default:
            {
                throw new IllegalArgumentException("Invalid device specification: " + deviceStr);
            }
    }
    if (dst == null || dst.length() == 0) {
        dst = src;
    }
    return new Device(permissions, dst, src);
}

