public String getNextAvailableNodeId(final String nodeId) {
    String result = nodeId;
    do {
        result = _primaryNodeIds.getNextNodeId(result);
        if (result != null && result.equals(nodeId)) {
            result = null;
        }
    } while (result != null && !isNodeAvailable(result));
    return result;
}

