    String noTZ = "yyyy:MM:dd:HH:mm:ss";
    if (dateString.length() == noTZ.length()) {
        return date(dateString, noTZ);
    } else if (dateString.length() == noTZ.length() + 4) {
        dateString = dateString + "00";
    }
    return date(dateString, "yyyy:MM:dd:HH:mm:ss:Z");
}

