public boolean hasText() {
    AtomicBoolean hasText = new AtomicBoolean(false);
    filter((node, depth) -> {
        if (node instanceof TextNode) {
            TextNode textNode = (TextNode) node;
            if (!textNode.isBlank()) {
                hasText.set(true);
                return NodeFilter.FilterResult.STOP;
            }
        }
        return NodeFilter.FilterResult.CONTINUE;
    });
    return hasText.get();
}

