@Nullable
public Element closest(Evaluator evaluator) {
    Validate.notNull(evaluator);
    Element el = this;
    final Element root = root();
    do {
        if (evaluator.matches(root, el))
            return el;
        el = el.parent();
    } while (el != null);
    return null;
}

