public static String rtrim(String pString) {
    if ((pString == null) || (pString.length() == 0)) {
        return pString;
    }
    for (int i = pString.length(); i > 0; i--) {
        if (!Character.isWhitespace(pString.charAt(i - 1))) {
            if (i == pString.length()) {
                return pString;
            } else {
                return pString.substring(0, i);
            }
        }
    }
    return "";
}

