@Override
public long skip(final long n) throws IOException {
    if (n <= 0) {
        return 0;
    }
    if (!buffer.hasRemaining()) {
        if (!fillBuffer()) {
            return 0;
        }
    }
    int length = (int) Math.min(n, buffer.remaining());
    buffer.position(buffer.position() + length);
    return length;
}

