public static String ltrim(String pString) {
    if ((pString == null) || (pString.length() == 0)) {
        return pString;
    }
    for (int i = 0; i < pString.length(); i++) {
        if (!Character.isWhitespace(pString.charAt(i))) {
            if (i == 0) {
                return pString;
            } else {
                return pString.substring(i);
            }
        }
    }
    return "";
}

