public static boolean isNumber(String pString) {
    if (isEmpty(pString)) {
        return false;
    }
    char ch = pString.charAt(0);
    if (!(ch == '-' || Character.isDigit(ch))) {
        return false;
    }
    for (int i = 1; i < pString.length(); i++) {
        if (!Character.isDigit(pString.charAt(i))) {
            return false;
        }
    }
    return true;
}

