    int length = colName.length();
    char c;
    int index = -1;
    for (int i = 0; i < length; i++) {
        c = Character.toUpperCase(colName.charAt(i));
        if (Character.isDigit(c)) {
            break;
        }
        index = (index + 1) * 26 + (int) c - 'A';
    }
    return index;
}

