public void isIntegerTest() {
    Assert.assertTrue(NumberUtil.isInteger("-12"));
    Assert.assertTrue(NumberUtil.isInteger("256"));
    Assert.assertTrue(NumberUtil.isInteger("0256"));
    Assert.assertTrue(NumberUtil.isInteger("0"));
