public static <K, V> void forEach(Map<K, V> map, KVConsumer<K, V> kvConsumer) {
    if (map == null) {
        return;
    }
    int index = 0;
    for (Entry<K, V> entry : map.entrySet()) {
        kvConsumer.accept(entry.getKey(), entry.getValue(), index);
        index++;
    }
}

