public static File touch(File file) throws IORuntimeException {
    if (null == file) {
        return null;
    }
    if (false == file.exists()) {
        mkParentDirs(file);
        try {
            file.createNewFile();
        } catch (Exception e) {
            throw new IORuntimeException(e);
        }
    }
    return file;
}

