public static String email(String email) {
    if (StrUtil.isBlank(email)) {
        return StrUtil.EMPTY;
    }
    int index = StrUtil.indexOf(email, '@');
    if (index <= 1) {
        return email;
    }
    return StrUtil.hide(email, 1, index);
}

