public static int hash32(byte[] data) {
    int len = data.length;
    if (len <= 24) {
        return len <= 12 ? (len <= 4 ? hash32Len0to4(data) : hash32Len5to12(data)) : hash32Len13to24(data);
    }
    int h = len, g = c1 * len, f = g;
    int a0 = rotate32(fetch32(data, len - 4) * c1, 17) * c2;
    int a1 = rotate32(fetch32(data, len - 8) * c1, 17) * c2;
    int a2 = rotate32(fetch32(data, len - 16) * c1, 17) * c2;
    int a3 = rotate32(fetch32(data, len - 12) * c1, 17) * c2;
    int a4 = rotate32(fetch32(data, len - 20) * c1, 17) * c2;
    h ^= a0;
    h = rotate32(h, 19);
    h = h * 5 + 0xe6546b64;
    h ^= a2;
    h = rotate32(h, 19);
    h = h * 5 + 0xe6546b64;
    g ^= a1;
    g = rotate32(g, 19);
    g = g * 5 + 0xe6546b64;
    g ^= a3;
    g = rotate32(g, 19);
    g = g * 5 + 0xe6546b64;
    f += a4;
    f = rotate32(f, 19);
    f = f * 5 + 0xe6546b64;
    int iters = (len - 1) / 20;
    int pos = 0;
    do {
        a0 = rotate32(fetch32(data, pos) * c1, 17) * c2;
        a1 = fetch32(data, pos + 4);
        a2 = rotate32(fetch32(data, pos + 8) * c1, 17) * c2;
        a3 = rotate32(fetch32(data, pos + 12) * c1, 17) * c2;
        a4 = fetch32(data, pos + 16);
        h ^= a0;
        h = rotate32(h, 18);
        h = h * 5 + 0xe6546b64;
        f += a1;
        f = rotate32(f, 19);
        f = f * c1;
        g += a2;
        g = rotate32(g, 18);
        g = g * 5 + 0xe6546b64;
        h ^= a3 + a1;
        h = rotate32(h, 19);
        h = h * 5 + 0xe6546b64;
        g ^= a4;
        g = Integer.reverseBytes(g) * 5;
        h += a4 * 5;
        h = Integer.reverseBytes(h);
        f += a0;
        int swapValue = f;
        f = g;
        g = h;
        h = swapValue;
        pos += 20;
    } while (--iters != 0);
    g = rotate32(g, 11) * c1;
    g = rotate32(g, 17) * c1;
    f = rotate32(f, 11) * c1;
    f = rotate32(f, 17) * c1;
    h = rotate32(h + g, 19);
    h = h * 5 + 0xe6546b64;
    h = rotate32(h, 17) * c1;
    h = rotate32(h + f, 19);
    h = h * 5 + 0xe6546b64;
    h = rotate32(h, 17) * c1;
    return h;
}

