public static String removeHtmlAttr(String content, String... attrs) {
    String regex;
    for (String attr : attrs) {
        regex = StrUtil.format("(?i)(\\s*{}\\s*=[^>]+?\\s+(?=>))|(\\s*{}\\s*=[^>]+?(?=\\s|>))", attr, attr);
        content = content.replaceAll(regex, StrUtil.EMPTY);
    }
    return content;
}

