public static char toCloseChar(char c) {
    int result = c;
    if (c >= '1' && c <= '9') {
        result = '①' + c - '1';
    } else if (c >= 'A' && c <= 'Z') {
        result = 'Ⓐ' + c - 'A';
    } else if (c >= 'a' && c <= 'z') {
        result = 'ⓐ' + c - 'a';
    }
    return (char) result;
}

