public static List<String> getNames(Class<? extends Enum<?>> clazz) {
    final Enum<?>[] enums = clazz.getEnumConstants();
    if (null == enums) {
        return null;
    }
    final List<String> list = new ArrayList<>(enums.length);
    for (Enum<?> e : enums) {
        list.add(e.name());
    }
    return list;
}

