String[] result = ArrayUtil.replace(a, -1, b);
Assert.assertArrayEquals(new String[] { "a", "b", "c", "1", "2", "3", "4" }, result);
// 在第0个位置开始替换，返回a
result = ArrayUtil.replace(ArrayUtil.clone(a), 0, b);
Assert.assertArrayEquals(new String[] { "a", "b", "c", "4" }, result);
