@Test
public void ringNextIntByObjTest() {
    final AtomicInteger atomicInteger = new AtomicInteger();
    // 开启并发测试，每个线程获取到的元素都是唯一的
    ThreadUtil.concurrencyTest(strList.size(), () -> {
