public static String idCardNum(String idCardNum, int front, int end) {
    if (StrUtil.isBlank(idCardNum)) {
        return StrUtil.EMPTY;
    }
    if ((front + end) > idCardNum.length()) {
        return StrUtil.EMPTY;
    }
    if (front < 0 || end < 0) {
        return StrUtil.EMPTY;
    }
    return StrUtil.hide(idCardNum, front, idCardNum.length() - end);
}

