    final StringBuilder builder = new StringBuilder(6);
    builder.append("\\u");
    String hex = toHex(value);
    int len = hex.length();
    if (len < 4) {
        builder.append("0000", 0, 4 - len);
    }
    builder.append(hex);
    return builder.toString();
}

