public void cloneTest() {
    Integer[] b = { 1, 2, 3 };
    Integer[] cloneB = ArrayUtil.clone(b);
    Assert.assertArrayEquals(b, cloneB);
    int[] a = { 1, 2, 3 };
    int[] clone = ArrayUtil.clone(a);
    Assert.assertArrayEquals(a, clone);
}

