    T result = ArrayUtil.clone(obj);
    if (null == result) {
        if (obj instanceof Cloneable) {
            result = ReflectUtil.invoke(obj, "clone");
        } else {
            result = cloneByStream(obj);
        }
    }
    return result;
}

