public static String indexToColName(int index) {
    if (index < 0) {
        return null;
    }
    final StringBuilder colName = StrUtil.builder();
    do {
        if (colName.length() > 0) {
            index--;
        }
        int remainder = index % 26;
        colName.append((char) (remainder + 'A'));
        index = (index - remainder) / 26;
    } while (index > 0);
    return colName.reverse().toString();
}

