public <T> Converter<T> getConverter(Type type, boolean isCustomFirst) {
    Converter<T> converter;
    if (isCustomFirst) {
        converter = this.getCustomConverter(type);
        if (null == converter) {
            converter = this.getDefaultConverter(type);
        }
    } else {
        converter = this.getDefaultConverter(type);
        if (null == converter) {
            converter = this.getCustomConverter(type);
        }
    }
    return converter;
}

