public static boolean isBetween(Number value, Number min, Number max) {
    Assert.notNull(value);
    Assert.notNull(min);
    Assert.notNull(max);
    final double doubleValue = value.doubleValue();
    return (doubleValue >= min.doubleValue()) && (doubleValue <= max.doubleValue());
}

