    if (StrUtil.isBlank(idCard)) {
        return false;
    }
    int length = idCard.length();
    switch(length) {
        case 18:
            return isValidCard18(idCard);
        case 15:
            return isValidCard15(idCard);
        case 10:
            {
                String[] cardVal = isValidCard10(idCard);
                return null != cardVal && "true".equals(cardVal[2]);
            }
        default:
            return false;
    }
}

