public static String removeAllHtmlAttr(String content, String... tagNames) {
    String regex;
    for (String tagName : tagNames) {
        regex = StrUtil.format("(?i)<{}[^>]*?>", tagName);
        content = content.replaceAll(regex, StrUtil.format("<{}>", tagName));
    }
    return content;
}

