public static <E> E get(final Iterator<E> iterator, int index) throws IndexOutOfBoundsException {
    if (null == iterator) {
        return null;
    }
    Assert.isTrue(index >= 0, "[index] must be >= 0");
    while (iterator.hasNext()) {
        index--;
        if (-1 == index) {
            return iterator.next();
        }
        iterator.next();
    }
    return null;
}

