@Override
public List<String> tokenize(String text) {
    String replaced = text.replaceAll("([Cc])['’‘ʼ]([Hh])", "$1\u0001\u0001BR@APOS\u0001\u0001$2").replaceAll("(\\p{L})['’‘ʼ]", "$1\u0001\u0001BR@APOS\u0001\u0001 ");
    List<String> tokenList = super.tokenize(replaced);
    List<String> tokens = new ArrayList<>();
    Iterator<String> itr = tokenList.iterator();
    while (itr.hasNext()) {
        String word = itr.next().replace("\u0001\u0001BR@APOS\u0001\u0001", "’");
        tokens.add(word);
        if (!word.equals("’") && word.endsWith("’")) {
            itr.next();
        }
    }
    return tokens;
}

