String replaceSpacesInRegex(String s) {
    StringBuilder sb = new StringBuilder();
    boolean inBracket = false;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '[') {
            inBracket = true;
        } else if (c == ']') {
            inBracket = false;
        }
        if (c == ' ' && !inBracket) {
            sb.append("(?:[\\s\u00A0\u202F]+)");
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

