private static final int maxPatterns = 7;
private final Pattern[] patterns = new Pattern[maxPatterns];
// Patterns to avoid splitting words in certain special cases
// apostrophe
private static final Pattern TYPEWRITER_APOSTROPHE = Pattern.compile("([\\p{L}])'([\\p{L}1\"‘“«])", Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
private static final Pattern TYPOGRAPHIC_APOSTROPHE = Pattern.compile("([\\p{L}])’([\\p{L}1\"‘“«])", Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
// nearby hyphens.
private static final Pattern NEARBY_HYPHENS = Pattern.compile("([\\p{L}])-([\\p{L}])-([\\p{L}])", Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
// hyphens.
private static final Pattern HYPHENS = Pattern.compile("([\\p{L}])-([\\p{L}\\d])", Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
// decimal point between digits
private static final Pattern DECIMAL_POINT = Pattern.compile("([\\d])\\.([\\d])", Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
// decimal comma between digits
private static final Pattern DECIMAL_COMMA = Pattern.compile("([\\d]),([\\d])", Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
// space between digits
// the first is an exception to the two next patterns
private static final Pattern SPACE_DIGITS0 = Pattern.compile("([\\d]{4}) ", Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
private static final Pattern SPACE_DIGITS = Pattern.compile("([\\d]) ([\\d][\\d][\\d])\\b", Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
private static final Pattern SPACE_DIGITS2 = Pattern.compile("([\\d]) ([\\d][\\d][\\d]) ([\\d][\\d][\\d])\\b", Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);
private static final List<String> doNotSplit = Arrays.asList("mers-cov", "mcgraw-hill", "sars-cov-2", "sars-cov", "ph-metre", "ph-metres", "anti-ivg", "anti-uv", "anti-vih", "al-qaïda", "c'est-à-dire", "add-on", "add-ons", "rendez-vous", "garde-à-vous", "chez-eux", "chez-moi", "chez-nous", "chez-soi", "chez-toi", "chez-vous", "m'as-tu-vu");
// the string used to tokenize characters
// hyphen
private final String frTokenizingChars = super.getTokenizingCharacters() + "-";

