public static boolean isAllMathsChars(String s) {
    if (s.length() % 2 != 0) {
        return false;
    }
    for (int i = 0; i < s.length(); i++) {
        if (i % 2 == 0) {
            if (s.charAt(i) != '\uD835') {
                return false;
            }
        } else {
            int numValue = s.charAt(i);
            if (numValue < MATHEMATICAL_BOLD_CAPITAL_A || numValue > MATHEMATICAL_MONOSPACE_DIGIT_NINE) {
                return false;
            }
        }
    }
    return true;
}

