@Override
public String getTranslationSuffix(String s) {
    StringBuilder sb = new StringBuilder();
    List<String> lookingFor = new ArrayList<>();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '[') {
            lookingFor.add("]");
        } else if (c == ']' && lookingFor.contains("]")) {
            sb.append(c);
            sb.append(' ');
            lookingFor.remove("]");
        } else if (c == '<') {
            lookingFor.add(">");
        } else if (c == '>' && lookingFor.contains(">")) {
            sb.append(c);
            sb.append(' ');
            lookingFor.remove(">");
        } else if (c == '(') {
            lookingFor.add(")");
        } else if (c == ')') {
            sb.append(c);
            sb.append(' ');
            lookingFor.remove(")");
        } else if (c == '{') {
            lookingFor.add("}");
        } else if (c == '}') {
            sb.append(c);
            sb.append(' ');
            lookingFor.remove("}");
        }
        if (lookingFor.size() > 0) {
            sb.append(c);
        }
    }
    return sb.toString().trim();
}

