                List<Language> langs = new ArrayList<>(token.langs);
                langs.add(secondLang);
                tokens.set(i, new TokenWithLanguages(token.token, langs));
            }
            i++;
        }
    }
    long t2 = System.nanoTime();
    long runTime = t2 - t1;
    return tokens;
}

