public int getBytes(int index, byte[] dst, int off, int len) {
    int count = Math.min(len, size - index);
    if (buf.hasArray()) {
        System.arraycopy(buf.array(), buf.arrayOffset() + index, dst, off, count);
    } else {
        ByteBuffer dup = buf.duplicate();
        dup.position(index);
        dup.get(dst, off, count);
    }
    return count;
}

