public PointList clone(boolean reverse) {
    PointList clonePL = new PointList(size(), is3D());
    if (is3D())
        for (int i = 0; i < size(); i++) {
            clonePL.add(this.getLat(i), this.getLon(i), this.getEle(i));
        }
    else
        for (int i = 0; i < size(); i++) {
            clonePL.add(this.getLat(i), this.getLon(i));
        }
    if (reverse)
        clonePL.reverse();
    return clonePL;
}

