@Override
public byte[] fromBitString(String str) {
    int strLen = str.length();
    int bLen = str.length() / 8;
    if (strLen % 8 != 0)
        bLen++;
    byte[] bytes = new byte[bLen];
    int charI = 0;
    for (int b = bLen - 1; b >= 0; b--) {
        byte res = 0;
        for (int i = 0; i < 8; i++) {
            res <<= 1;
            if (charI < strLen && str.charAt(charI) != '0')
                res |= 1;
            charI++;
        }
        bytes[b] = res;
    }
    return bytes;
}

