public static String camelCaseToUnderScore(String key) {
    if (key.isEmpty())
        return key;
    StringBuilder sb = new StringBuilder(key.length());
    for (int i = 0; i < key.length(); i++) {
        char c = key.charAt(i);
        if (Character.isUpperCase(c))
            sb.append("_").append(Character.toLowerCase(c));
        else
            sb.append(c);
    }
    return sb.toString();
}

