static double atan2(double y, double x) {
    double absY = Math.abs(y) + 1e-10;
    double r, angle;
    if (x < 0.0) {
        r = (x + absY) / (absY - x);
        angle = PI3_4;
    } else {
        r = (x - absY) / (x + absY);
        angle = PI_4;
    }
    angle += (0.1963 * r * r - 0.9817) * r;
    if (y < 0.0)
        return -angle;
    return angle;
}

